const rnd = (a, b) => a + Math.random() * (b - a);
function shuffleArray(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}
function hex(h) { h = h.replace('#', ''); return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)]; }
function mix(a, b, t) {
  const A = hex(a), B = hex(b);
  return '#' + A.map((v, k) => Math.round(v + (B[k] - v) * t).toString(16).padStart(2, '0')).join('');
}

// The splash: flat fill, or a "scene" (speckled gradient) clipped inside the shape.
function shapeSVG(shape, pal, scene, id, animate) {
  const anim = a => animate ? a : '';
  let defs = '', inner = '';
  if (scene) {
    const light = mix(pal.fill, '#FFFFFF', 0.34), deep = mix(pal.fill, '#000000', 0.16);
    defs += '<clipPath id="c' + id + '"><path d="' + shape.body + '"/></clipPath>' +
      '<linearGradient id="g' + id + '" x1="0.1" y1="0" x2="0.8" y2="1">' +
      '<stop offset="0" stop-color="' + light + '"/><stop offset="1" stop-color="' + deep + '"/></linearGradient>' +
      '<filter id="b' + id + '" x="-40%" y="-40%" width="180%" height="180%">' +
      '<feGaussianBlur stdDeviation="1.6"/></filter>';
    let body = '<rect x="-30" y="-30" width="160" height="160" fill="url(#g' + id + ')"/>';
    let bok = '';
    for (let k = 0; k < 6; k++) {
      bok += '<circle class="pin" cx="' + rnd(6, 94).toFixed(1) + '" cy="' + rnd(6, 94).toFixed(1) +
        '" r="' + rnd(5, 17).toFixed(1) + '" fill="#ffffff" opacity="' + rnd(.14, .32).toFixed(2) + '"' +
        anim(' style="--bx:' + rnd(-3, 3).toFixed(1) + 'px;--by:' + rnd(-4, -1).toFixed(1) + 'px;' +
          '--bd:' + rnd(7, 14).toFixed(1) + 's;--bdl:' + (-rnd(0, 9)).toFixed(1) + 's"') + '/>';
    }
    body += '<g filter="url(#b' + id + ')">' + bok + '</g>';
    const hues = ['#FFFFFF', mix(pal.fill, '#FFFFFF', .62), mix(pal.fill, '#000000', .34)];
    for (let k = 0; k < 11; k++) {
      const w = rnd(1.6, 3.1), h = w * rnd(2.0, 3.4), x = rnd(4, 94), y = rnd(4, 94), rot = rnd(-70, 70);
      const spin = animate
        ? ' style="--rot:' + rot.toFixed(0) + 'deg;--spin:' + rnd(-22, 22).toFixed(0) + 'deg;' +
          '--bx:' + rnd(-2.5, 2.5).toFixed(1) + 'px;--by:' + rnd(-2.5, 2.5).toFixed(1) + 'px;' +
          '--bd:' + rnd(6, 12).toFixed(1) + 's;--bdl:' + (-rnd(0, 8)).toFixed(1) + 's"'
        : ' transform="rotate(' + rot.toFixed(0) + ' ' + (x + w / 2).toFixed(1) + ' ' + (y + h / 2).toFixed(1) + ')"';
      body += '<rect class="pin" x="' + x.toFixed(1) + '" y="' + y.toFixed(1) + '" width="' + w.toFixed(1) +
        '" height="' + h.toFixed(1) + '" rx="' + (w * 0.42).toFixed(2) + '" fill="' + hues[k % 3] +
        '" opacity="' + rnd(.42, .78).toFixed(2) + '"' + spin + '/>';
    }
    inner += '<g clip-path="url(#c' + id + ')">' + body + '</g>';
  } else {
    inner += '<path d="' + shape.body + '" fill="' + pal.fill + '"/>';
  }
  shape.drops.forEach((d, k) => {
    inner += '<path class="drop" d="' + d.d + '" fill="' + pal.fill + '"' +
      anim(' style="--dx:' + d.dx + 'px;--dy:' + d.dy + 'px;--d:' + (60 + k * 42) + 'ms"') + '/>';
  });
  return { defs, inner };
}

let uid = 0;
function credit(card) {
  return (card.author ? esc(card.author) + ' · ' : '') + 'found by <b>' + esc(card.spotter) + '</b>';
}

function makeSlot(shape, pal, card) {
  const s = document.createElement('div');
  s.className = 'slot';
  const el = document.createElement('div');
  el.className = 'layer in';
  const rot = Math.random() * 20 - 10;
  el.style.setProperty('--r', rot.toFixed(1) + 'deg');
  el.style.setProperty('--r0', (rot - 24).toFixed(1) + 'deg');
  const id = ++uid;
  const g = shapeSVG(shape, pal, !!card.scene, id, true);
  el.innerHTML = '<svg class="shape" viewBox="0 0 100 100" aria-hidden="true">' +
    (g.defs ? '<defs>' + g.defs + '</defs>' : '') + g.inner + '</svg>';

  const b = shape.box, p = document.createElement('div');
  p.className = 'plaque';
  p.style.cssText = 'color:' + pal.text + ';left:' + (b.cx - b.w / 2) + '%;top:' + (b.cy - b.h / 2) +
    '%;width:' + b.w + '%;height:' + b.h + '%';
  if (card.kind === 'intro') {
    p.innerHTML = '<span class="introMark">DOBANESS<i></i></span>' +
      '<p class="introLine">' + esc(card.line) + '</p>';
  } else {
    const extra = card.kind === 'post' ? '<span class="found">' + credit(card) + '</span>'
      : '<span class="cta">' + esc(card.cta) + '</span>';
    p.innerHTML = '<span class="axis">' + esc(card.axis) + '</span>' +
      '<p class="joke">' + esc(card.joke) + '</p>' + extra;
  }
  el.appendChild(p);
  s.appendChild(el);

  if (card.kind === 'sponsor' || card.kind === 'callout') {
    const go = () => { card.kind === 'sponsor' ? openPanel('taskbee') : openAddWidget(card.axisFor); };
    s.querySelectorAll('svg.shape > path, svg.shape > g, .plaque')
      .forEach(n => n.addEventListener('click', e => { e.stopPropagation(); go(); }));
  }
  return s;
}

function fitText(el) {
  const p = el.querySelector('.plaque'); if (!p) return;
  let fs = p.clientWidth / 7.4;
  p.style.setProperty('--fs', fs.toFixed(2) + 'px');
  let guard = 40;
  while ((p.scrollHeight > p.clientHeight + 1 || p.scrollWidth > p.clientWidth + 1) && fs > 7 && guard--) {
    fs *= 0.94; p.style.setProperty('--fs', fs.toFixed(2) + 'px');
  }
}

/* ---------------------------------------------------------------------
   CONTENT MODEL — real seed posts mapped to the card shape, plus
   in-feed sponsor (Taskbee) and callout ("your turn") cards.
--------------------------------------------------------------------- */
const POSTS = SEED_POSTS.map(p => ({
  id: p.id,
  axisCode: p.axis,
  axis: p.origin || (AXIS_BY_KEY[p.axis] || {}).title || p.axis,
  joke: p.body,
  spotter: p.handle,
  setup: '',
  kind: 'post',
  mine: null,
}));

const ASKS = {
  matatu: 'Heard a crazy conductor line today?',
  mtaa: 'Landlord or jirani said something mad?',
  situ: 'Got left on read with a wild excuse?',
  comr: 'Spotted a wild campus comment?',
  bunge: 'Mbunge amesema kitu ngumu?',
  other: 'Seen a wild comment on X or TikTok today?',
};
function calloutCard(axisCode) {
  return {
    kind: 'callout', axis: 'Your turn', axisFor: axisCode, scene: false, setup: '',
    pal: { fill: '#2A2521', text: '#FFFFFF' },
    joke: ASKS[axisCode] || ASKS.other, cta: 'Drop it here →',
  };
}
function taskbeeCard() {
  return {
    kind: 'sponsor', axis: 'Brand slot', scene: true, setup: '',
    pal: { fill: '#F2B21C', text: '#33240A' },
    joke: TASKBEE.line, cta: TASKBEE.url + ' →',
  };
}

function buildFeed() {
  const posts = shuffleArray(POSTS);
  const feed = [];
  posts.forEach((p, k) => {
    feed.push(Object.assign({}, p, { mine: null }));
    if (k === Math.floor(posts.length * 0.18) || k === Math.floor(posts.length * 0.62)) {
      feed.push(calloutCard(p.axisCode));
    }
    if (k > 0 && k % 16 === 11) feed.push(taskbeeCard());
  });
  feed.forEach((c, k) => { if (c.scene === undefined) c.scene = ((k + Math.floor(k / SHAPES.length)) % 2) === 1; });
  return feed;
}

