let feed = [];
let i = -1, shapeN = 0, palN = 0, slot = null, timer = null;
let currentCard = null, currentPal = null, currentShape = null, cardBorn = 0;
let introShowing = true;

function restartTimer() {
  clearTimeout(timer);
  timerEl.classList.remove('run'); void timerEl.offsetWidth;
  if (panelOpen || introShowing) return;
  timerEl.classList.add('run');
  timer = setTimeout(() => advance(false), HOLD);
}
function pauseTimer() { clearTimeout(timer); timerEl.classList.remove('run'); }

function advance(manual) {
  if (currentCard && currentCard.kind !== 'intro') {
    const dwell = performance.now() - cardBorn;
    const splashId = currentCard.kind === 'post' ? currentCard.id : currentCard.kind;
    track('splash_dismissed', { post_id: splashId, dwell_ms: Math.round(dwell), method: manual ? 'tap' : 'timer' });
    if (manual) gaEvent('splash_tap', { splash_id: currentCard.kind === 'post' ? currentCard.id : null, bundle: currentCard.axisCode || null });
  }
  i = (i + 1) % feed.length;
  showCard(feed[i]);
}

function showCard(card) {
  const shape = SHAPES[(shapeN++) % SHAPES.length];
  const pal = card.pal || PALETTE[(palN++) % PALETTE.length];

  const old = slot;
  if (old) { old.classList.add('gone'); setTimeout(() => { if (old.parentNode) old.remove(); }, 520); }
  slot = makeSlot(shape, pal, card);
  stageEl.appendChild(slot);
  fitText(slot.querySelector('.layer'));
  currentCard = card; currentPal = pal; currentShape = shape;
  cardBorn = performance.now();

  if (card.setup) { setupEl.innerHTML = 'This landed <b>' + esc(card.setup) + '</b>.'; setupEl.classList.remove('blank'); }
  else setupEl.classList.add('blank');

  renderActions(card, pal);
  countEl.textContent = pad(i + 1) + ' / ' + pad(feed.length);
  timerEl.style.background = pal.fill;
  tapHint.textContent = card.kind === 'post' ? 'Tap the wall for the next splash' : 'Tap the splash to open it';

  if (card.kind === 'post') track('splash_shown', { post_id: card.id, axis: card.axisCode, tier: TIER });
  restartTimer();
}

/* ---------------------------------------------------------------------
   REACTIONS — batched, flushed on timer/pagehide, no fabricated counts
--------------------------------------------------------------------- */
let pendingReactions = [];
function reactTo(card, key) {
  const was = card.mine === key;
  card.mine = was ? null : key;
  gaEvent('splash_react', { splash_id: card.id, bundle: card.axisCode, reaction: key });
  if (!was) {
    pendingReactions.push({ post_id: card.id, emoji: key, bundle: card.axisCode, session_id: SESSION_ID });
    track('reaction', { post_id: card.id, emoji: key });
  }
}

function renderActions(card, pal) {
  reactionsEl.innerHTML = '';
  if (card.kind === 'sponsor' || card.kind === 'callout') {
    const b = document.createElement('button');
    b.className = 'bigcta';
    b.textContent = card.kind === 'sponsor' ? 'About Taskbee' : 'Drop a find';
    b.addEventListener('click', e => {
      e.stopPropagation();
      card.kind === 'sponsor' ? openPanel('taskbee') : openAddWidget(card.axisFor);
    });
    reactionsEl.appendChild(b);
    return;
  }
  const btns = [];
  REACTION_SET.forEach(r => {
    const b = document.createElement('button');
    b.className = 'react';
    b.classList.toggle('on', card.mine === r.key);
    b.style.setProperty('--hue', pal.fill);
    b.innerHTML = '<span class="em">' + r.emoji + '</span>' + r.label;
    b.addEventListener('click', e => {
      e.stopPropagation();
      reactTo(card, r.key);
      btns.forEach(x => x.el.classList.toggle('on', card.mine === x.key));
      b.classList.add('pop'); setTimeout(() => b.classList.remove('pop'), 170);
      restartTimer();
    });
    btns.push({ key: r.key, el: b });
    reactionsEl.appendChild(b);
  });
}

wallEl.addEventListener('click', () => {
  if (panelOpen) return;
  if (introShowing) return;
  advance(true);
});

document.addEventListener('keydown', e => {
  if (introShowing) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); dismissIntro(); } return; }
  if (panelOpen) { if (e.key === 'Escape') closePanel(); return; }
  const ae = document.activeElement;
  const typing = ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA' || ae.tagName === 'SELECT');
  if (typing) return;
  if (e.key === ' ' || e.key === 'ArrowRight') {
    e.preventDefault();
    advance(true);
  } else if (['1', '2', '3'].includes(e.key) && currentCard && currentCard.kind === 'post') {
    reactTo(currentCard, REACTION_SET[Number(e.key) - 1].key);
    renderActions(currentCard, currentPal);
    restartTimer();
  }
});

window.addEventListener('resize', () => {
  TIER = computeTier();
  if (slot) fitText(slot.querySelector('.layer'));
});

document.addEventListener('visibilitychange', () => {
  if (document.hidden) { pauseTimer(); flushBatches(true); }
  else if (!panelOpen && !introShowing) restartTimer();
});

if (document.fonts && document.fonts.ready) {
  document.fonts.ready.then(() => { if (slot) fitText(slot.querySelector('.layer')); });
}

/* ---------------------------------------------------------------------
   ANALYTICS — D1-bound event log, batched; GA4 gets a separate,
   smaller, PII-free taxonomy.
--------------------------------------------------------------------- */
let pendingAnalytics = [];
const sessionStart = performance.now();
let splashesSeen = 0;

function track(event, fields) {
  if (event === 'splash_shown') splashesSeen++;
  pendingAnalytics.push(Object.assign({ event, t: Date.now(), session_id: SESSION_ID }, fields || {}));
}
function gaEvent(name, params) {
  if (typeof window.gtag === 'function') window.gtag('event', name, params || {});
}
function flushBatches(useBeacon) {
  if (pendingReactions.length) {
    const body = JSON.stringify(pendingReactions);
    if (useBeacon && navigator.sendBeacon) navigator.sendBeacon('/api/react', new Blob([body], { type: 'application/json' }));
    else fetch('/api/react', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body, keepalive: true }).catch(() => {});
    pendingReactions = [];
  }
  if (pendingAnalytics.length) {
    const body = JSON.stringify(pendingAnalytics);
    if (useBeacon && navigator.sendBeacon) navigator.sendBeacon('/api/events', new Blob([body], { type: 'application/json' }));
    else fetch('/api/events', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body, keepalive: true }).catch(() => {});
    pendingAnalytics = [];
  }
}
setInterval(() => flushBatches(false), 5000);
window.addEventListener('pagehide', () => {
  track('session', { tier: TIER, splashes_seen: splashesSeen, duration_ms: Math.round(performance.now() - sessionStart) });
  flushBatches(true);
});

/* ---------------------------------------------------------------------
   API + TOAST
--------------------------------------------------------------------- */
async function api(path, opts) {
  const res = await fetch(path, Object.assign({ headers: { 'Content-Type': 'application/json' } }, opts));
  const body = await res.json().catch(() => ({}));
  if (!res.ok || body.ok === false) throw Object.assign(new Error(body.error || 'request failed'), { status: res.status, body });
  return body;
}
let toastTimer = null;
function toast(msg) {
  const el = document.getElementById('toast');
  el.textContent = msg;
  el.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove('show'), 2600);
}

/* ---------------------------------------------------------------------
   FOCUS TRAP
--------------------------------------------------------------------- */
function trapFocus(container) {
  let prevFocused = null;
  function focusables() {
    return Array.from(container.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])'))
      .filter(el => !el.disabled && el.offsetParent !== null);
  }
  function onKeydown(e) {
    if (e.key !== 'Tab') return;
    const items = focusables();
    if (!items.length) return;
    const first = items[0], last = items[items.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  }
  return {
    activate() {
      prevFocused = document.activeElement;
      container.addEventListener('keydown', onKeydown);
      const items = focusables();
      if (items.length) items[0].focus();
    },
    deactivate() {
      container.removeEventListener('keydown', onKeydown);
      if (prevFocused && prevFocused.focus) prevFocused.focus();
    },
  };
}

