function openPanel(view) {
  panelOpen = view;
  panelEl.innerHTML = PANEL[view]();
  panelEl.classList.add('open');
  panelEl.setAttribute('aria-hidden', 'false');
  panelVeil.classList.add('show');
  pauseTimer();
  wirePanelView(view);
  if (panelTrap) panelTrap.deactivate();
  panelTrap = trapFocus(panelEl);
  panelTrap.activate();
  track('widget_opened', { widget: view });
  if (view === 'add-widget') gaEvent('submit_start', {});
  else if (view === 'claim-widget') gaEvent('slot_claim_start', { entry: pendingSlotClaimEntry });
}
function closePanel() {
  if (!panelOpen) return;
  panelEl.classList.remove('open');
  panelEl.setAttribute('aria-hidden', 'true');
  panelVeil.classList.remove('show');
  if (panelTrap) panelTrap.deactivate();
  panelOpen = null;
  if (!introShowing) restartTimer();
}
function openAddWidget(axisFor) {
  presetAxis = axisFor || null;
  openPanel('add-widget');
}
panelVeil.addEventListener('click', closePanel);

function wirePanelView(view) {
  panelEl.querySelectorAll('[data-pclose]').forEach(b => b.addEventListener('click', closePanel));
  panelEl.querySelectorAll('[data-goto]').forEach(b => b.addEventListener('click', () => openPanel(b.dataset.goto)));

  if (view === 'claim-form') wireClaimSlotForm();
  else if (view === 'add-form') wireAddToWallForm();
  else if (view === 'report') wireReportForm();
  else if (view === 'share') wireShareForm();
}

function wireClaimSlotForm() {
  const brand = panelEl.querySelector('#cs-brand');
  const contact = panelEl.querySelector('#cs-contact');
  const wa = panelEl.querySelector('#cs-wa');
  const waErr = panelEl.querySelector('#cs-wa-err');
  const bundleSel = panelEl.querySelector('#cs-bundle');
  const notes = panelEl.querySelector('#cs-notes');
  const submit = panelEl.querySelector('#cs-submit');

  bundleSel.insertAdjacentHTML('beforeend', AXES.map(a => `<option value="${a.key}">${a.emoji} ${a.title}</option>`).join(''));

  function validate() {
    const waOk = PHONE_RE.test(wa.value.replace(/[\s-]/g, ''));
    submit.disabled = !(brand.value.trim().length >= 2 && contact.value.trim().length >= 2 && waOk);
  }
  [brand, contact, wa].forEach(el => el.addEventListener('input', () => { waErr.classList.remove('show'); validate(); }));
  validate();

  submit.addEventListener('click', async () => {
    const payload = {
      brand_name: brand.value.trim(),
      contact_name: contact.value.trim(),
      whatsapp: wa.value.replace(/[\s-]/g, ''),
      bundle_pref: bundleSel.value || null,
      notes: notes.value.trim().slice(0, 280) || null,
      entry: pendingSlotClaimEntry,
      session_id: SESSION_ID,
    };
    submit.disabled = true; submit.textContent = 'Reserving…';
    try {
      await api('/api/claim-slot', { method: 'POST', body: JSON.stringify(payload) });
      track('action_completed', { action: 'claim-slot' });
      gaEvent('slot_claim_complete', { bundle_pref: payload.bundle_pref });
      panelEl.querySelectorAll('.field, #cs-submit, .p-title, .p-body, .p-note').forEach(el => el.style.display = 'none');
      panelEl.querySelector('#cs-success').classList.add('show');
    } catch (err) {
      waErr.textContent = err.message || 'something went wrong';
      waErr.classList.add('show');
      submit.textContent = 'Reserve a slot';
      validate();
    }
  });
}

function wireAddToWallForm() {
  const axisSel = panelEl.querySelector('#ad-axis');
  axisSel.innerHTML = AXES.map(a => `<option value="${a.key}">${a.emoji} ${a.title}</option>`).join('');
  if (presetAxis) { axisSel.value = presetAxis; presetAxis = null; }
  const body = panelEl.querySelector('#ad-body');
  const seen = panelEl.querySelector('#ad-seen');
  const counter = panelEl.querySelector('#ad-counter');
  const submit = panelEl.querySelector('#ad-submit');

  function validate() {
    const wc = wordCount(body.value);
    const wcOk = wc >= 7 && wc <= 9;
    counter.textContent = wc + ' words' + (wcOk ? '' : ' — needs 7 to 9');
    counter.classList.toggle('bad', !wcOk);
    submit.disabled = !wcOk;
  }
  body.addEventListener('input', validate);
  validate();

  submit.addEventListener('click', async () => {
    const axis = axisSel.value;
    const payload = { body: body.value.trim(), axis, seen_at: seen.value.trim() || null, session_id: SESSION_ID };
    submit.disabled = true; submit.textContent = 'Adding…';
    try {
      await api('/api/submit', { method: 'POST', body: JSON.stringify(payload) });
      track('action_completed', { action: 'add-to-wall' });
      gaEvent('submit_complete', { bundle: axis });
      panelEl.querySelectorAll('.field, #ad-submit, .p-title, .p-body').forEach(el => {
        if (!el.closest('#ad-success')) el.style.display = 'none';
      });
      panelEl.querySelector('#ad-success').classList.add('show');
      gaEvent('name_claim_start', { splash_id: null });
      wireClaimNameForm();
    } catch (err) {
      submit.textContent = 'Add to the wall';
      validate();
      toast(err.message || 'something went wrong');
    }
  });
}

function wireClaimNameForm() {
  const name = panelEl.querySelector('#ad-name');
  const nameErr = panelEl.querySelector('#ad-name-err');
  const wa = panelEl.querySelector('#ad-wa');
  const submit = panelEl.querySelector('#ad-claim-submit');

  function normName() { return name.value.trim().replace(/^@/, '').toLowerCase(); }
  function validate() {
    submit.disabled = !(HANDLE_RE.test(normName()) && PHONE_RE.test(wa.value.replace(/[\s-]/g, '')));
  }
  [name, wa].forEach(el => el.addEventListener('input', () => { nameErr.classList.remove('show'); validate(); }));
  validate();

  submit.addEventListener('click', async () => {
    const payload = { handle: normName(), whatsapp: wa.value.replace(/[\s-]/g, ''), splash_id: null, session_id: SESSION_ID };
    submit.disabled = true; submit.textContent = 'Claiming…';
    try {
      await api('/api/claim-name', { method: 'POST', body: JSON.stringify(payload) });
      track('action_completed', { action: 'claim-name' });
      gaEvent('name_claim_complete', { splash_id: null });
      [name, wa, submit].forEach(el => el.style.display = 'none');
      panelEl.querySelector('#ad-claim-success').classList.add('show');
    } catch (err) {
      nameErr.textContent = err.message || 'something went wrong';
      nameErr.classList.add('show');
      submit.textContent = 'Claim my name';
      validate();
    }
  });
}

// Not backed by any endpoint — an explicit product choice (no takedown
// table exists yet). The report text still lands somewhere real: the
// existing analytics event log, instead of being silently discarded.
function wireReportForm() {
  const what = panelEl.querySelector('#rp-what');
  const who = panelEl.querySelector('#rp-who');
  const submit = panelEl.querySelector('#rp-submit');
  submit.addEventListener('click', () => {
    if (!what.value.trim()) { toast('Tell us which splash'); return; }
    track('takedown_request', {
      post_id: currentCard && currentCard.kind === 'post' ? currentCard.id : null,
      note: what.value.trim().slice(0, 400),
      contact: who.value.trim().slice(0, 60),
    });
    flushBatches(false);
    panelEl.querySelectorAll('.field, #rp-submit, .p-title, .p-body').forEach(el => el.style.display = 'none');
    panelEl.querySelector('#rp-success').classList.add('show');
  });
}

/* ---------------------------------------------------------------------
   SHARE — mints a tracked URL via /api/share, then composites a
   1080×1920 image of the current splash for Web Share / clipboard.
--------------------------------------------------------------------- */
async function mintShareUrl(splashId) {
  try {
    const res = await api('/api/share', { method: 'POST', body: JSON.stringify({ splash_id: splashId || null, session_id: SESSION_ID }) });
    if (res && res.url) return res.url;
  } catch (e) { /* fall through to the plain URL below */ }
  return location.origin + location.pathname;
}

const CARD_W = 1080, CARD_H = 1920;
function svgToImage(str) {
  return new Promise((res, rej) => {
    const blob = new Blob([str], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(blob), im = new Image();
    im.onload = () => { URL.revokeObjectURL(url); res(im); };
    im.onerror = e => { URL.revokeObjectURL(url); rej(e); };
    im.src = url;
  });
}
function wrapText(ctx, text, maxW) {
  const words = text.split(/\s+/), lines = []; let line = '';
  words.forEach(w => {
    const t = line ? line + ' ' + w : w;
    if (ctx.measureText(t).width > maxW && line) { lines.push(line); line = w; } else line = t;
  });
  if (line) lines.push(line);
  return lines;
}
function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  if (ctx.roundRect) ctx.roundRect(x, y, w, h, r);
  else {
    ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath();
  }
}
async function renderShareCard(card, pal, shape, caption) {
  const cv = document.createElement('canvas'); cv.width = CARD_W; cv.height = CARD_H;
  const ctx = cv.getContext('2d');
  ctx.fillStyle = '#E9E4D9'; ctx.fillRect(0, 0, CARD_W, CARD_H);
  const rg = ctx.createRadialGradient(CARD_W / 2, CARD_H * 0.16, 40, CARD_W / 2, CARD_H * 0.16, CARD_W * 1.15);
  rg.addColorStop(0, 'rgba(255,255,255,.42)'); rg.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = rg; ctx.fillRect(0, 0, CARD_W, CARD_H);

  const g = shapeSVG(shape, pal, !!card.scene, 'x', false);
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="1000" viewBox="0 0 100 100">' +
    (g.defs ? '<defs>' + g.defs + '</defs>' : '') + g.inner + '</svg>';
  const img = await svgToImage(svg);
  const hasTop = !!(card.setup || (caption && caption.trim()));
  const S = 1000, sx = (CARD_W - S) / 2, sy = CARD_H * (hasTop ? 0.30 : 0.26);
  ctx.save();
  ctx.shadowColor = 'rgba(40,32,24,.26)'; ctx.shadowBlur = 48; ctx.shadowOffsetY = 26;
  ctx.drawImage(img, sx, sy, S, S);
  ctx.restore();

  const b = shape.box, bw = b.w / 100 * S, bh = b.h / 100 * S;
  const bx = sx + (b.cx / 100 * S), by = sy + (b.cy / 100 * S);
  const sub = card.kind === 'post' ? 'found by ' + card.spotter : card.cta;
  let fs = bw / 8.2, lines, pillH, subLines, total, lh;
  for (let guard = 0; guard < 40; guard++) {
    ctx.font = '400 ' + fs.toFixed(1) + 'px "Archivo Black","Arial Black",sans-serif';
    lines = wrapText(ctx, card.joke, bw); lh = fs * 1.16;
    pillH = fs * 0.40 * 2.1;
    ctx.font = '500 ' + (fs * 0.46).toFixed(1) + 'px "Space Grotesk",sans-serif';
    subLines = wrapText(ctx, sub, bw);
    total = pillH + fs * 0.55 + lines.length * lh + fs * 0.45 + subLines.length * fs * 0.62;
    if (total <= bh) break;
    fs *= 0.94;
  }
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  let y = by - total / 2;
  ctx.font = '700 ' + (fs * 0.40).toFixed(1) + 'px "Space Grotesk",sans-serif';
  const pw = ctx.measureText(card.axis).width + fs * 0.72;
  ctx.fillStyle = 'rgba(255,255,255,.93)';
  roundRect(ctx, bx - pw / 2, y, pw, pillH, pillH / 2); ctx.fill();
  ctx.fillStyle = '#2b2521'; ctx.fillText(card.axis, bx, y + pillH / 2 + 1);
  y += pillH + fs * 0.55;
  ctx.fillStyle = pal.text;
  ctx.font = '400 ' + fs.toFixed(1) + 'px "Archivo Black","Arial Black",sans-serif';
  lines.forEach(l => { ctx.fillText(l, bx, y + lh / 2); y += lh; });
  y += fs * 0.45;
  ctx.globalAlpha = .88;
  ctx.font = '500 ' + (fs * 0.46).toFixed(1) + 'px "Space Grotesk",sans-serif';
  subLines.forEach(l => { ctx.fillText(l, bx, y + fs * 0.31); y += fs * 0.62; });
  ctx.globalAlpha = 1;

  let ty = CARD_H * 0.105;
  if (caption && caption.trim()) {
    ctx.fillStyle = '#221E1B';
    let cfs = 52, clines;
    for (let guard = 0; guard < 20; guard++) {
      ctx.font = '700 ' + cfs + 'px "Space Grotesk",sans-serif';
      clines = wrapText(ctx, caption.trim(), CARD_W - 180);
      if (clines.length <= 3) break;
      cfs -= 4;
    }
    clines.forEach(l => { ctx.fillText(l, CARD_W / 2, ty); ty += cfs * 1.24; });
    ty += 18;
  }

  ctx.fillStyle = '#221E1B';
  ctx.font = '400 58px "Archivo Black","Arial Black",sans-serif';
  ctx.fillText('DOBANESS', CARD_W / 2, CARD_H - 138);
  ctx.beginPath();
  ctx.arc(CARD_W / 2 + ctx.measureText('DOBANESS').width / 2 + 22, CARD_H - 138, 9, 0, 6.29); ctx.fill();
  ctx.globalAlpha = .62;
  ctx.font = '500 30px "Space Grotesk",sans-serif';
  ctx.fillText('dobaness.com', CARD_W / 2, CARD_H - 78);
  ctx.globalAlpha = 1;
  return cv;
}

function wireShareForm() {
  const img = panelEl.querySelector('#share-preview');
  const cap = panelEl.querySelector('#share-caption');
  const go = panelEl.querySelector('#share-go');
  const copy = panelEl.querySelector('#share-copy');
  async function refresh() {
    try {
      const cv = await renderShareCard(currentCard, currentPal, currentShape, cap.value);
      img.src = cv.toDataURL('image/png');
    } catch (e) { /* leave the preview blank if compositing fails */ }
  }
  refresh();
  let t = null;
  cap.addEventListener('input', () => { clearTimeout(t); t = setTimeout(refresh, 350); });

  go.addEventListener('click', async () => {
    go.disabled = true; const prev = go.textContent; go.textContent = 'Making the image…';
    const splashId = currentCard && currentCard.kind === 'post' ? currentCard.id : null;
    let channel = 'other';
    try {
      const url = await mintShareUrl(splashId);
      const cv = await renderShareCard(currentCard, currentPal, currentShape, cap.value);
      const blob = await new Promise(r => cv.toBlob(r, 'image/png'));
      const file = new File([blob], 'dobaness-splash.png', { type: 'image/png' });
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({ files: [file], title: 'DOBANESS', text: url });
      } else if (navigator.share) {
        await navigator.share({ title: 'DOBANESS', text: 'A wall of Kenyan comments.', url });
      } else {
        const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'dobaness-splash.png'; a.click();
        setTimeout(() => URL.revokeObjectURL(a.href), 4000);
        channel = 'copy_link';
        toast('Image saved');
      }
      track('share', { channel, splash_id: splashId });
      gaEvent('share_click', { channel, splash_id: splashId });
      closePanel();
    } catch (err) { toast("Couldn't make the image"); }
    go.disabled = false; go.textContent = prev;
  });

  copy.addEventListener('click', async () => {
    const c = currentCard;
    const splashId = c && c.kind === 'post' ? c.id : null;
    const text = c.kind === 'post' ? '"' + c.joke + '" — ' + c.axis + ' on DOBANESS' : c.joke + ' — DOBANESS';
    try {
      const url = await mintShareUrl(splashId);
      await navigator.clipboard.writeText(text + '\n' + url);
      toast('Copied to clipboard');
      track('share', { channel: 'copy_link', splash_id: splashId });
      gaEvent('share_click', { channel: 'copy_link', splash_id: splashId });
    } catch (e) { toast("Couldn't copy"); }
  });
}

document.getElementById('share').addEventListener('click', e => { e.stopPropagation(); openPanel('share'); });
document.getElementById('dropfind').addEventListener('click', e => { e.stopPropagation(); openAddWidget(null); });
document.getElementById('brandslots').addEventListener('click', e => {
  e.stopPropagation(); pendingSlotClaimEntry = 'button'; openPanel('claim-widget');
});
document.getElementById('takedown').addEventListener('click', e => { e.stopPropagation(); openPanel('report'); });

// Inbound share visit: ?r={token} — record it, then clean the URL.
(function handleShareReturn() {
  const params = new URLSearchParams(location.search);
  const token = params.get('r');
  if (!token) return;
  track('share_return', { share_token: token });
  gaEvent('share_return', { share_token: token });
  params.delete('r'); params.delete('s');
  const clean = location.pathname + (params.toString() ? '?' + params.toString() : '') + location.hash;
  history.replaceState(null, '', clean);
})();

// dobaness.com/claim — a direct entry point for the sales conversation:
// loads the wall and opens the slot form immediately.
if (new URLSearchParams(location.search).get('claim') === '1') {
  pendingSlotClaimEntry = 'deeplink';
  window.addEventListener('load', () => {
    dismissIntro();
    openPanel('claim-form');
    const params = new URLSearchParams(location.search);
    params.delete('claim');
    history.replaceState(null, '', location.pathname + (params.toString() ? '?' + params.toString() : ''));
  });
}

/* ---------------------------------------------------------------------
   INTRO SCREEN — a real dialog (live stats, privacy disclosure), its
   decorative blob rendered through the same shapeSVG() path as the wall.
--------------------------------------------------------------------- */
const introStageEl = document.getElementById('introStage');

function showIntro() {
  const shape = SHAPES[3 % SHAPES.length];
  const pal = { fill: '#E85568', text: '#FFFFFF' };
  const id = ++uid;
  const g = shapeSVG(shape, pal, true, id, true);
  const wrap = document.createElement('div');
  wrap.className = 'layer in';
  const rot = Math.random() * 20 - 10;
  wrap.style.setProperty('--r', rot.toFixed(1) + 'deg');
  wrap.style.setProperty('--r0', (rot - 24).toFixed(1) + 'deg');
  wrap.innerHTML = '<svg class="shape" viewBox="0 0 100 100" aria-hidden="true">' +
    (g.defs ? '<defs>' + g.defs + '</defs>' : '') + g.inner + '</svg>';
  introStageEl.appendChild(wrap);
}
introStageEl.addEventListener('click', () => dismissIntro());

// Live splash count — the span already carries the build-time fallback
// (real seed count), so never a spinner, never a 0.
async function loadIntroStats() {
  try {
    const res = await fetch('/api/stats', { signal: AbortSignal.timeout(2500) });
    const data = await res.json();
    if (data && typeof data.splashes === 'number') {
      document.getElementById('intro-count').textContent = data.splashes;
    }
    if (data && typeof data.founding_slots_left === 'number') {
      foundingSlotsLeft = data.founding_slots_left;
    }
  } catch (e) { /* keep the build-time fallback already in the DOM */ }
}

function dismissIntro() {
  if (!introShowing) return;
  introShowing = false;
  document.getElementById('intro').classList.add('hide');
  track('action_completed', { action: 'enter-wall' });
  track('wall_enter', {});
  gaEvent('wall_enter', {});
  advance(false);
}
document.getElementById('intro-enter').addEventListener('click', dismissIntro);

